        collect_labels_expr(ls, e->u.un.operand);
        break;
    case EX_INC_DEC:
        collect_labels_expr(ls, e->u.incdec.operand);
        break;
    case EX_BINOP:
        collect_labels_expr(ls, e->u.bin.l);
        collect_labels_expr(ls, e->u.bin.r);
